<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const data=ref({sources:[],documents:[],queryCount:0}),keyword=ref('审批'),hits=ref([]),context=ref(''),msg=ref('');async function load(){try{data.value=await request('/api/search-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function search(){try{const r=await request('/api/search-ops/search',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',userKey:'operator',groups:'operations',keyword:keyword.value})});hits.value=r.hits;context.value=r.answerContext;msg.value=r.hits.length?`返回 ${r.hits.length} 条权限内结果`:'没有找到权限内结果'}catch(e){msg.value=e.message}}async function create(){try{await request('/api/search-ops/sources',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',sourceCode:'SRC-'+Date.now(),name:'企业制度中心',sourceType:'DOCUMENT'})});msg.value='知识源已登记，等待管理员启用';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>ENTERPRISE KNOWLEDGE SEARCH</small><h3>权限感知知识检索</h3><p>在用户与用户组边界内检索企业知识，并返回可验证的来源引用。</p></div><button @click="create">连接知识源</button></section><section class="search"><input v-model="keyword" @keyup.enter="search" placeholder="搜索制度、手册、案例或业务知识"><button @click="search">检索</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>知识数据源</span><b>{{data.sources.length}}</b><small>文档与业务系统</small></article><article><span>索引文档</span><b>{{data.documents.length}}</b><small>内容摘要可校验</small></article><article><span>累计查询</span><b>{{data.queryCount}}</b><small>运营与评测基础</small></article></section><section class="board"><article><header><h4>检索结果</h4><button @click="load">刷新状态</button></header><div class="row" v-for="x in hits" :key="x.documentId"><div><b>{{x.title}}</b><small>{{x.snippet}}</small><code>{{x.citation}}</code></div><em>{{x.score}}</em></div><p v-if="!hits.length">输入关键词检索当前账号有权查看的知识。</p></article><article><header><h4>检索增强上下文</h4><span>可配置模型适配器</span></header><pre>{{context||'搜索结果会在这里组装为带引用上下文；项目仅预留模型对接方式。'}}</pre></article></section></template>
<style scoped>.head{padding:27px 30px;border-radius:14px;background:#283248;color:#fff;display:flex;justify-content:space-between;align-items:end}.head small{color:#aab9dd;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#d2d9e8}.head button,.search button{border:0;border-radius:8px;padding:11px 17px;background:#e3b15b;color:#273147;font-weight:700}.search{display:flex;gap:10px;margin:16px 0;background:white;padding:12px;border:1px solid #dfe4ed;border-radius:12px}.search input{flex:1;border:0;outline:0;padding:0 8px;font-size:15px}.msg{padding:10px 14px;background:#f2f4f9;border-left:3px solid #5a6f9f}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:white;border:1px solid #dfe4ed;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#6d7587}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.board header,.row{display:flex;justify-content:space-between;align-items:start}.board header{padding-bottom:12px;border-bottom:1px solid #e9ecf2}.board header button{border:0;background:transparent;color:#536c9c}.row{padding:14px 0;border-bottom:1px solid #edf0f5;gap:15px}.row small,.row code{display:block;color:#758093;margin-top:5px}.row code{color:#536c9c}.row em{font-style:normal;font-weight:700;color:#4a6190}pre{white-space:pre-wrap;line-height:1.7;color:#586174;background:#f7f8fb;border-radius:8px;padding:14px}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
